DELETE FROM MOHECORE.[LU_STUDENT_PORTAL_ACCOUNT_STATUS] WHERE (CODE LIKE 'QA[-_0-9]%' OR CODE LIKE 'QAT[_]%' OR CODE LIKE 'QAUI%') AND IS_SYSTEM = 0 AND (NAME_EN LIKE '%QA%' OR NAME_AR LIKE '%QA%');
SET @n = @@ROWCOUNT; SET @total += @n; IF @n > 0 PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  LU_STUDENT_PORTAL_ACCOUNT_STATUS');
DELETE FROM MOHECORE.[LU_TREND_CLASS] WHERE (CODE LIKE 'QA[-_0-9]%' OR CODE LIKE 'QAT[_]%' OR CODE LIKE 'QAUI%') AND IS_SYSTEM = 0 AND (NAME_EN LIKE '%QA%' OR NAME_AR LIKE '%QA%');
SET @n = @@ROWCOUNT; SET @total += @n; IF @n > 0 PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  LU_TREND_CLASS');
