DELETE FROM UMSCORE.UMS_Reports WHERE Id = 62 AND ReportCode = 'QAUI_REPORT_041003';
SET @n = @@ROWCOUNT; SET @total += @n; PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  UMS_Reports QAUI_REPORT_041003');
DELETE FROM ALERTCORE.ApprovalSteps WHERE RequestId IN (20867,20868,20869,21644,21645,21646,21647,21648,21649,21650,21651,21652,21653,21654,21655,21656,21657,21658,21659,21660,21661,21662,21663,21664,21665,21666,21667,21668,21669,21670,21671,21672,21673,21674,21675,21676,21677,21678,21679,21680,21681,21682,21683,21684,21685,21686,21687,21688,21689,21690,21691,21692,21693,21694,21695,21696,21697,21698,21699,21700,21701,21702,21703,21704,21705,21706,21707,21708,21709,21710,21711,21712,21713,21714,21715,21716,21717,21718,21719,21720,21721,21722,21723,21724);
SET @n = @@ROWCOUNT; SET @total += @n; PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  ApprovalSteps of QA requests');
DELETE FROM ALERTCORE.ApprovalHistory WHERE RequestId IN (20867,20868,20869,21644,21645,21646,21647,21648,21649,21650,21651,21652,21653,21654,21655,21656,21657,21658,21659,21660,21661,21662,21663,21664,21665,21666,21667,21668,21669,21670,21671,21672,21673,21674,21675,21676,21677,21678,21679,21680,21681,21682,21683,21684,21685,21686,21687,21688,21689,21690,21691,21692,21693,21694,21695,21696,21697,21698,21699,21700,21701,21702,21703,21704,21705,21706,21707,21708,21709,21710,21711,21712,21713,21714,21715,21716,21717,21718,21719,21720,21721,21722,21723,21724);
SET @n = @@ROWCOUNT; SET @total += @n; PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  ApprovalHistory of QA requests');
DELETE FROM ALERTCORE.ApprovalRequests WHERE Id IN (20867,20868,20869,21644,21645,21646,21647,21648,21649,21650,21651,21652,21653,21654,21655,21656,21657,21658,21659,21660,21661,21662,21663,21664,21665,21666,21667,21668,21669,21670,21671,21672,21673,21674,21675,21676,21677,21678,21679,21680,21681,21682,21683,21684,21685,21686,21687,21688,21689,21690,21691,21692,21693,21694,21695,21696,21697,21698,21699,21700,21701,21702,21703,21704,21705,21706,21707,21708,21709,21710,21711,21712,21713,21714,21715,21716,21717,21718,21719,21720,21721,21722,21723,21724) AND RequestedAt >= '2026-09-21';
SET @n = @@ROWCOUNT; SET @total += @n; PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  ApprovalRequests of the QA rounds');
DELETE FROM ALERTCORE.ApprovalLevelApprovers WHERE LevelId = 38;
SET @n = @@ROWCOUNT; SET @total += @n; PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  ApprovalLevelApprovers of QA level');
DELETE FROM ALERTCORE.ApprovalLevels WHERE Id = 38 AND ConfigId = 21;
SET @n = @@ROWCOUNT; SET @total += @n; PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  ApprovalLevels of QA config');
DELETE FROM ALERTCORE.ApprovalConfigs WHERE Id = 21 AND EntityType = 'QA_UI_0924_044542';
SET @n = @@ROWCOUNT; SET @total += @n; PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  ApprovalConfigs QA_UI_0924_044542');
DELETE FROM MOHECORE.StudentInfoRequestStaging WHERE RequestId IN (949,950,951);
SET @n = @@ROWCOUNT; SET @total += @n; PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  StudentInfoRequestStaging 949-951');
DELETE FROM MOHECORE.StudentInfoRequest WHERE Id IN (949,950,951) AND Title LIKE '%QA-%';
SET @n = @@ROWCOUNT; SET @total += @n; PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  StudentInfoRequest 949-951');
DELETE FROM MOHECORE.StudentInquiry WHERE Id IN (3,4) AND Title LIKE 'QA%';
SET @n = @@ROWCOUNT; SET @total += @n; PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  StudentInquiry 3,4');
DELETE FROM MOHECORE.STUDENT_DOCUMENT_HISTORY WHERE HISTORY_ID IN (83,84) AND DOCUMENT_ID IN (3624,3625);
SET @n = @@ROWCOUNT; SET @total += @n; PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  STUDENT_DOCUMENT_HISTORY 83,84');
DELETE FROM MOHECORE.STUDENT_DOCUMENTS WHERE DOCUMENT_ID IN (3624,3625) AND DOCUMENT_NAME LIKE 'QA%';
