DELETE FROM FINCORE.COA_ACCOUNT WHERE ACCOUNT_ID IN (2967,2968) AND NAME_EN LIKE 'QA%';
SET @n = @@ROWCOUNT; SET @total += @n; PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  COA_ACCOUNT 2967,2968');
