SET @n = @@ROWCOUNT; SET @total += @n; PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  STUDENT_FINANCE 3 restored (pre 21 Sep values, request 20867)');
