SET @n = @@ROWCOUNT; SET @total += @n; PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  STUDENT_FINANCE 1003 restored (pre 23 Sep values, request 21667)');
UPDATE MOHECORE.STUDENT_FINANCE SET STUDY_CHECK_DATE = NULL, STUDY_FIN_RECIEVED_STATUS = 99 WHERE STUDENT_ID IN (10065, 10066) AND CAST(STUDY_NOTE_1 AS NVARCHAR(MAX)) = N'ZZ-SCOPE-SEED' AND STUDY_FIN_RECIEVED_STATUS = 1 AND STUDY_CHECK_DATE = '2026-09-21 19:24:20.810';
SET @n = @@ROWCOUNT; SET @total += @n; PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  STUDENT_FINANCE of scope-seed copies of student 3 (status/cheque date inherited from the QA edit)');
UPDATE MOHECORE.STUDENT_DATA_ARCH SET STUDENT_NOTE_1 = NULL WHERE ID = 945 AND STUDENT_ID = 4 AND CAST(STUDENT_NOTE_1 AS NVARCHAR(MAX)) = N'QA-TEST';
SET @n = @@ROWCOUNT; SET @total += @n; PRINT CONCAT(RIGHT('     ' + CAST(@n AS NVARCHAR(10)), 5), '  STUDENT_DATA_ARCH 945 note cleared (QA-TEST written by an earlier probe)');

PRINT CONCAT(@total, ' rows affected in total');

/* ---- What is left (audit tables excluded on purpose) ---- */
DECLARE @left NVARCHAR(MAX) = N'';
IF EXISTS (SELECT 1 FROM MOHECORE.STUDENT_DATA WHERE STUDENT_NAME LIKE 'QA-%') SET @left += N' STUDENT_DATA';
IF EXISTS (SELECT 1 FROM MOHECORE.STUDENT_FINANCE WHERE STUDENT_FIN_NAME LIKE 'QA-%' OR CAST(STUDY_NOTE_1 AS NVARCHAR(MAX)) LIKE '%QA[-_ ]%' OR STUDY_CHECK_ID LIKE 'QA-%') SET @left += N' STUDENT_FINANCE';
IF EXISTS (SELECT 1 FROM UMSCORE.Users WHERE Username LIKE 'qa%' OR Username LIKE 'sa-test-%') SET @left += N' Users';
IF EXISTS (SELECT 1 FROM UMSCORE.Roles WHERE RoleName LIKE 'QA-%') SET @left += N' Roles';
IF EXISTS (SELECT 1 FROM UMSCORE.UserGroups WHERE GroupName LIKE 'QA-%') SET @left += N' UserGroups';
IF EXISTS (SELECT 1 FROM UMSCORE.Resources WHERE ResourceCode LIKE '%QAUI%') SET @left += N' Resources';
IF EXISTS (SELECT 1 FROM ALERTCORE.ApprovalRequests WHERE CAST(RequestData AS NVARCHAR(MAX)) LIKE '%QA-LIVE%' OR CAST(RequestData AS NVARCHAR(MAX)) LIKE '%QA-UI%' OR CAST(RequestData AS NVARCHAR(MAX)) LIKE '%QA-TEST%') SET @left += N' ApprovalRequests';
IF EXISTS (SELECT 1 FROM ALERTCORE.ApprovalConfigs WHERE EntityType LIKE 'QA%') SET @left += N' ApprovalConfigs';
IF EXISTS (SELECT 1 FROM MOHECORE.StudentInquiry WHERE Title LIKE 'QA%') SET @left += N' StudentInquiry';
IF EXISTS (SELECT 1 FROM MOHECORE.StudentInfoRequest WHERE Title LIKE '%QA-%') SET @left += N' StudentInfoRequest';
IF EXISTS (SELECT 1 FROM FINCORE.COA_ACCOUNT WHERE NAME_EN LIKE 'QA%') SET @left += N' COA_ACCOUNT';
IF EXISTS (SELECT 1 FROM FINCORE.BUDGET_APPROPRIATION WHERE REFERENCE_NUMBER LIKE 'QA-%') SET @left += N' BUDGET_APPROPRIATION';
IF @left = N'' PRINT 'No QA-tagged rows left in the business tables.';
ELSE PRINT CONCAT('WARNING - QA-tagged rows remain in:', @left);

IF @Commit = 1
BEGIN
    COMMIT;
    PRINT 'COMMITTED';
END
ELSE
BEGIN
    ROLLBACK;
    PRINT 'ROLLED BACK (dry run) - set @Commit = 1 to apply';
END
